package com.estradaplay.patriota;
import android.content.Context;import org.json.*;import java.util.*;
final class RoadQualityStore{private static final String P="epp_road_quality_v160",K="cells";static final class Point{final double lat,lon;final int score,count;Point(double a,double b,int s,int c){lat=a;lon=b;score=s;count=c;}}private final Context app;RoadQualityStore(Context c){app=c.getApplicationContext();}synchronized void record(RoadSurfaceMonitor.Impact x){if(x==null)return;try{JSONArray a=raw(),out=new JSONArray();String key=key(x.lat,x.lon);JSONObject hit=null;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&key.equals(o.optString("key"))){hit=o;break;}}if(hit==null){hit=new JSONObject();hit.put("key",key);hit.put("lat",x.lat);hit.put("lon",x.lon);hit.put("count",0);hit.put("force_sum",0);}hit.put("count",hit.optInt("count")+1);hit.put("force_sum",hit.optDouble("force_sum")+Math.max(0,x.force));hit.put("at",System.currentTimeMillis());out.put(hit);for(int i=0;i<a.length()&&out.length()<400;i++){JSONObject o=a.optJSONObject(i);if(o==null||key.equals(o.optString("key")))continue;out.put(o);}app.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}synchronized ArrayList<Point> around(double lat,double lon,double meters){ArrayList<Point> out=new ArrayList<>();JSONArray a=raw();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;double la=o.optDouble("lat"),lo=o.optDouble("lon");if(RoadPackStore.distanceM(lat,lon,la,lo)>meters)continue;int count=Math.max(1,o.optInt("count",1));double avg=o.optDouble("force_sum")/count;int score=(int)Math.max(10,Math.min(95,100-count*6-avg*4));out.add(new Point(la,lo,score,count));}return out;}synchronized int scoreNear(double lat,double lon){ArrayList<Point>a=around(lat,lon,2500);if(a.isEmpty())return 100;double s=0,w=0;for(Point p:a){double ww=Math.max(1,p.count);s+=p.score*ww;w+=ww;}return (int)Math.round(s/w);}private JSONArray raw(){try{return new JSONArray(app.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}private String key(double a,double b){return String.format(java.util.Locale.US,"%.3f:%.3f",a,b);}}
